func TestURLEncodedParam(t *testing.T) {
	mux := NewRouter()
	mux.Get("/", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("root"))
	})
	mux.Get("/files/{name}", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("file=" + URLParam(r, "name")))
	})
	mux.Get("/files/{name}/meta", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("meta=" + URLParam(r, "name")))
	})
	mux.Get("/files/*", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("wild=" + URLParam(r, "*")))
	})

	tests := []struct {
		name   string
		target string
		mutate func(*http.Request)
		status int
		body   string
	}{
		{
			// %2F must stay inside the param and not split the segment.
			name:   "encoded slash is not a separator",
			target: "/files/docs%2Freport.pdf",
			status: http.StatusOK,
			body:   "file=docs%2Freport.pdf",
		},
		{
			name:   "encoded slash with trailing static segment",
			target: "/files/docs%2Freport.pdf/meta",
			status: http.StatusOK,
			body:   "meta=docs%2Freport.pdf",
		},
		{
			name:   "unencoded path still matches",
			target: "/files/report.pdf",
			status: http.StatusOK,
			body:   "file=report.pdf",
		},
		{
			// RawPath is empty here ("%25" is the default encoding of "%"),
			// so matching must use the escaped form rather than URL.Path.
			name:   "literal percent stays escaped",
			target: "/files/50%25.txt",
			status: http.StatusOK,
			body:   "file=50%25.txt",
		},
		{
			// A prefix-stripping middleware or proxy rewrites URL.Path and
			// leaves URL.RawPath pointing at the original, encoded request.
			name:   "stale RawPath after Path rewrite",
			target: "/api/files/docs%2Freport.pdf",
			mutate: func(req *http.Request) {
				req.URL.Path = "/files/docs/report.pdf" // RawPath left stale
			},
			status: http.StatusOK,
			body:   "wild=docs/report.pdf",
		},
		{
			name:   "empty path falls back to /",
			target: "/api",
			mutate: func(req *http.Request) {
				req.URL.Path = ""
			},
			status: http.StatusOK,
			body:   "root",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			req := httptest.NewRequest("GET", tt.target, nil)
			if tt.mutate != nil {
				tt.mutate(req)
			}

			w := httptest.NewRecorder()
			mux.ServeHTTP(w, req)

			if w.Code != tt.status {
				t.Fatalf("%s: got status %d (%s), want %d",
					tt.target, w.Code, http.StatusText(w.Code), tt.status)
			}
			if got := w.Body.String(); got != tt.body {
				t.Fatalf("%s: got body %q, want %q", tt.target, got, tt.body)
			}
		})
	}
}
