-	// Route path resolution
-	routePath := r.URL.RawPath
-	if routePath == "" {
-		routePath = r.URL.Path
-	}
+	// Route path resolution.
+	//
+	// Match against the escaped path: EscapedPath() returns RawPath when it is
+	// a valid encoding of Path, and re-escapes Path otherwise. Reading RawPath
+	// directly is wrong in both directions - net/url leaves it empty whenever
+	// the default encoding of Path round-trips, and leaves it stale when a
+	// middleware rewrites r.URL.Path - so encoded segments such as %2F ended up
+	// matched in their decoded form and split across path segments.
+	routePath := r.URL.EscapedPath()
