```go
// TestURLEncodedParam covers issue #641: routing must run against the escaped
// request path so percent-encoded characters stay inside a single path segment,
// and so rewrites of r.URL.Path by upstream middleware are honoured.
func TestURLEncodedParam(t *testing.T) {
	echoParam := func(key string) http.HandlerFunc {
		return func(w http.ResponseWriter, r *http.Request) {
			w.Write([]byte(URLParam(r, key)))
		}
	}

	do := func(t *testing.T, h http.Handler, target string) (int, string) {
		t.Helper()
		w := httptest.NewRecorder()
		h.ServeHTTP(w, httptest.NewRequest("GET", target, nil))
		return w.Code, w.Body.String()
	}

	t.Run("encoded slash stays within one param", func(t *testing.T) {
		mux := NewRouter()
		mux.Get("/files/{name}", echoParam("name"))

		code, body := do(t, mux, "/files/docs%2Freport.pdf")
		if code != http.StatusOK {
			t.Fatalf("expected route match for '/files/docs%%2Freport.pdf', but got %d %s",
				code, http.StatusText(code))
		}
		if body != "docs%2Freport.pdf" {
			t.Fatalf("param should keep its encoding: got %q, want %q", body, "docs%2Freport.pdf")
		}
		got, err := url.PathUnescape(body)
		if err != nil || got != "docs/report.pdf" {
			t.Fatalf("PathUnescape(%q) = %q, %v; want %q", body, got, err, "docs/report.pdf")
		}
	})

	t.Run("encoded characters round-trip", func(t *testing.T) {
		mux := NewRouter()
		mux.Get("/files/{name}", echoParam("name"))

		cases := map[string]string{
			"/files/my%20file.txt": "my file.txt",
			"/files/100%25.txt":    "100%.txt",
			"/files/a%3Fb.txt":     "a?b.txt",
			"/files/caf%C3%A9.txt": "café.txt",
		}
		for target, want := range cases {
			code, body := do(t, mux, target)
			if code != http.StatusOK {
				t.Fatalf("%s: got %d, want 200", target, code)
			}
			got, err := url.PathUnescape(body)
			if err != nil {
				t.Fatalf("%s: PathUnescape(%q): %v", target, body, err)
			}
			if got != want {
				t.Fatalf("%s: param = %q, want %q", target, got, want)
			}
		}
	})

	t.Run("encoded slash in wildcard", func(t *testing.T) {
		mux := NewRouter()
		mux.Get("/static/*", echoParam("*"))

		code, body := do(t, mux, "/static/js%2Fapp.min.js")
		if code != http.StatusOK {
			t.Fatalf("got %d, want 200", code)
		}
		if body != "js%2Fapp.min.js" {
			t.Fatalf("wildcard = %q, want %q", body, "js%2Fapp.min.js")
		}
	})

	t.Run("unencoded path is unaffected", func(t *testing.T) {
		mux := NewRouter()
		mux.Get("/files/{name}", echoParam("name"))

		code, body := do(t, mux, "/files/report.pdf")
		if code != http.StatusOK || body != "report.pdf" {
			t.Fatalf("got %d %q, want 200 %q", code, body, "report.pdf")
		}
	})

	t.Run("rewritten r.URL.Path wins over stale RawPath", func(t *testing.T) {
		mux := NewRouter()
		mux.Get("/files/{name}", echoParam("name"))

		// Middleware such as a custom rewrite or http.StripPrefix typically
		// updates only r.URL.Path, leaving RawPath describing the original
		// request. Routing must follow the rewrite, not the stale RawPath.
		rewrite := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			r.URL.Path = "/files/report.pdf"
			mux.ServeHTTP(w, r)
		})

		code, body := do(t, rewrite, "/files/docs%2Freport.pdf")
		if code != http.StatusOK || body != "report.pdf" {
			t.Fatalf("got %d %q, want 200 %q", code, body, "report.pdf")
		}
	})

	t.Run("empty path falls back to /", func(t *testing.T) {
		mux := NewRouter()
		mux.Get("/", func(w http.ResponseWriter, r *http.Request) {
			w.Write([]byte("root"))
		})

		req := (&http.Request{Method: "GET", URL: &url.URL{}}).WithContext(context.Background())
		w := httptest.NewRecorder()
		mux.ServeHTTP(w, req)
		if w.Code != http.StatusOK || w.Body.String() != "root" {
			t.Fatalf("got %d %q, want 200 %q", w.Code, w.Body.String(), "root")
		}
	})
}
